const systemPrompt = `You are an intent-classification engine for a freelancer's personal operations assistant.
You ONLY interpret intent. You NEVER perform calculations, NEVER invent data, and NEVER modify anything.

Return ONLY a single JSON object, no prose, no markdown fences, matching exactly:
{"command":"<ONE_OF_ALLOWED_COMMANDS>","confidence":<0..1 number>,"parameters":{...}}

Allowed commands:
ADD_LEAD, LIST_LEADS, GET_LEAD, UPDATE_LEAD, CHANGE_STATUS, UPDATE_DEAL_VALUE,
RECORD_INTERACTION, ADD_NOTE, GET_LEAD_HISTORY,
CREATE_FOLLOW_UP, COMPLETE_FOLLOW_UP, UPDATE_FOLLOW_UP, CANCEL_FOLLOW_UP, LIST_FOLLOW_UPS,
DAILY_PRIORITY, PIPELINE_ANALYTICS, REVENUE_ANALYTICS, LEAD_ANALYTICS,
UNKNOWN

Parameter fields you may extract (omit any you cannot find in the message, never invent values):
business_name, contact_name, email, phone, service, status, deal_value, currency,
notes, interaction_type, content, follow_up_date, interval_days, report_type, filter.

Rules:
- If the message is ambiguous or missing information required to act, still return your best-guess command but set confidence below 0.6 and omit the missing fields.
- Never fabricate a business_name, date, or amount that was not stated by the user.
- If you cannot classify at all, return command "UNKNOWN".
- Output raw JSON only.`;

const userText = $json.text;

return [{
  json: {
    chatId: $json.chatId,
    userId: $json.userId,
    requestBody: {
      temperature: 0,
      systemPrompt,
      userText
    }
  }
}];

const REQUIRED = {
  ADD_LEAD: ['business_name'],
  LIST_LEADS: [],
  GET_LEAD: ['business_name'],
  UPDATE_LEAD: ['business_name'],
  CHANGE_STATUS: ['business_name', 'status'],
  UPDATE_DEAL_VALUE: ['business_name', 'deal_value'],
  RECORD_INTERACTION: ['business_name'],
  ADD_NOTE: ['business_name', 'notes'],
  GET_LEAD_HISTORY: ['business_name'],
  CREATE_FOLLOW_UP: ['business_name'],
  COMPLETE_FOLLOW_UP: ['business_name'],
  UPDATE_FOLLOW_UP: ['business_name'],
  CANCEL_FOLLOW_UP: ['business_name'],
  LIST_FOLLOW_UPS: [],
  DAILY_PRIORITY: [],
  PIPELINE_ANALYTICS: [],
  REVENUE_ANALYTICS: [],
  LEAD_ANALYTICS: [],
  UNKNOWN: []
};

const ALLOWED_STATUS = ['NEW','CONTACTED','REPLIED','QUALIFIED','PROPOSAL_SENT','NEGOTIATION','WON','LOST'];

// Maps common phrasing Gemini might return to the exact enum value the DB expects.
const STATUS_ALIASES = {
  'PROPOSAL': 'PROPOSAL_SENT',
  'PROPOSAL SENT': 'PROPOSAL_SENT',
  'SENT PROPOSAL': 'PROPOSAL_SENT',
  'SEND PROPOSAL': 'PROPOSAL_SENT',
  'CONTACT': 'CONTACTED',
  'REPLY': 'REPLIED',
  'REPLIED TO': 'REPLIED',
  'QUALIFY': 'QUALIFIED',
  'NEGOTIATE': 'NEGOTIATION',
  'NEGOTIATING': 'NEGOTIATION',
  'WIN': 'WON',
  'CLOSED WON': 'WON',
  'LOSE': 'LOST',
  'CLOSED LOST': 'LOST',
  'NEW LEAD': 'NEW'
};

const chatId = $('Build Gemini Request').first().json.chatId;
const userId = $('Build Gemini Request').first().json.userId;

let parsed = null;
try {
  const raw = $input.first().json;
  const candidate = raw.candidates && raw.candidates[0];
  if (raw.error || !candidate || !candidate.content || !candidate.content.parts) throw new Error('gemini_error');
  let text = candidate.content.parts.map(p => p.text || '').join('');
  text = text.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: { chatId, userId, command: 'UNKNOWN', confidence: 0, parameters: {}, missing: [], systemError: true } }];
}

let command = typeof parsed.command === 'string' ? parsed.command.toUpperCase().trim() : 'UNKNOWN';
if (!(command in REQUIRED)) command = 'UNKNOWN';

let confidence = typeof parsed.confidence === 'number' ? parsed.confidence : 0;
let parameters = (parsed.parameters && typeof parsed.parameters === 'object') ? parsed.parameters : {};

if (parameters.status) {
  let s = String(parameters.status).toUpperCase().trim();
  if (STATUS_ALIASES[s]) s = STATUS_ALIASES[s];
  parameters.status = s;
  if (!ALLOWED_STATUS.includes(parameters.status)) {
    parameters._invalidStatus = parameters.status;
    delete parameters.status;
  }
}

if (parameters.deal_value !== undefined) {
  const v = Number(String(parameters.deal_value).toString().replace(/[^0-9.\-]/g, ''));
  parameters.deal_value = isNaN(v) ? undefined : v;
}

const missing = (REQUIRED[command] || []).filter(f => parameters[f] === undefined || parameters[f] === null || parameters[f] === '');

return [{
  json: { chatId, userId, command, confidence, parameters, missing, systemError: false }
}];
